The program calculates n-th Fibonacci Number. The statement t = fun ( n-1, fp ) gives the (n-1)th Fibonacci number and *fp is used to store the (n-2)th Fibonacci Number. The initial value of *fp (which is 15 in the above program) doesn't matter. The following recursion tree shows all steps from 1 to 10, for the execution of fun(5, &x).                                (1) fun(5, fp)                              /           \                         (2) fun(4, fp)   (8) t = 3, f = 5, *fp = 3                         /          \                   (3) fun(3, fp)    (7) t = 2, f = 3, *fp = 2                  /            \              (4) fun(2, fp)   (6) t = 1, f = 2, *fp = 1             /         (5) *fp = 1  Question 5 : Predict the output of the following program.
            C++

    using namespace std;

int minIndex(int arr[], int s, int e)
{
    int sml = INT32_MAX;
    int mindex;
    for (int i = s; i < e; i++) {
        if (sml > arr[i]) {
            sml = arr[i];
            mindex = i;
        }
    }
    return mindex;
}

void fun2(int arr[], int start_index, int end_index)
{
    if (start_index >= end_index)
        return;
    int min_index;
    int temp;

    // minIndex() returns index of minimum value in
    // array arr[start_index...end_index] 
    min_index = minIndex(arr, start_index, end_index);

    // swap the element at start_index and min_index
    temp = arr[start_index];
    arr[start_index] = arr[min_index];
    arr[min_index] = temp;

    fun2(arr, start_index + 1, end_index);
}

// Driver code

int main()
{
    int arr[] = {64, 25, 12, 22, 11};
    int n = sizeof(arr) / sizeof(arr[0]);

    fun2(arr, 0, n);

    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
    cout << endl;


    return 0;
}


